const originalItems = $('Attach run id').all();

function bytesToText(bytes) {
  try {
    return new TextDecoder().decode(Uint8Array.from(bytes));
  } catch {
    return '';
  }
}

function tryParseJson(text) {
  if (typeof text !== 'string') return null;

  const trimmed = text.trim();
  if (!trimmed) return null;

  try {
    return JSON.parse(trimmed);
  } catch {
    return null;
  }
}

function collectReadableStateBytes(value) {
  const buffers = value?._readableState?.buffer;

  if (!Array.isArray(buffers)) {
    return [];
  }

  const bytes = [];

  for (const item of buffers) {
    if (item?.type === 'Buffer' && Array.isArray(item.data)) {
      bytes.push(...item.data);
      continue;
    }

    if (Array.isArray(item?.data)) {
      bytes.push(...item.data);
      continue;
    }
  }

  return bytes;
}

function extractEmbeddingArrayFromText(text) {
  if (typeof text !== 'string') return null;

  const marker = '"embedding":[';
  const markerIndex = text.indexOf(marker);

  if (markerIndex === -1) {
    return null;
  }

  const arrayStart = markerIndex + marker.length - 1;
  let depth = 0;
  let arrayEnd = -1;

  for (let i = arrayStart; i < text.length; i++) {
    const ch = text[i];

    if (ch === '[') depth++;
    if (ch === ']') depth--;

    if (depth === 0) {
      arrayEnd = i;
      break;
    }
  }

  if (arrayEnd === -1) return null;

  const arrayText = text.slice(arrayStart, arrayEnd + 1);

  try {
    const arr = JSON.parse(arrayText);
    if (Array.isArray(arr) && arr.every(x => typeof x === 'number')) {
      return arr;
    }
  } catch {
    return null;
  }

  return null;
}

function extractEmbedding(json) {
  if (Array.isArray(json?.data?.[0]?.embedding)) {
    return json.data[0].embedding;
  }

  if (Array.isArray(json?.body?.data?.[0]?.embedding)) {
    return json.body.data[0].embedding;
  }

  if (Array.isArray(json?.response?.data?.[0]?.embedding)) {
    return json.response.data[0].embedding;
  }

  if (typeof json?.body === 'string') {
    const parsed = tryParseJson(json.body);
    if (Array.isArray(parsed?.data?.[0]?.embedding)) {
      return parsed.data[0].embedding;
    }

    const extracted = extractEmbeddingArrayFromText(json.body);
    if (Array.isArray(extracted)) return extracted;
  }

  if (typeof json?.data === 'string') {
    const parsed = tryParseJson(json.data);
    if (Array.isArray(parsed?.data?.[0]?.embedding)) {
      return parsed.data[0].embedding;
    }

    const extracted = extractEmbeddingArrayFromText(json.data);
    if (Array.isArray(extracted)) return extracted;
  }

  const bytes = collectReadableStateBytes(json);

  if (bytes.length > 0) {
    const text = bytesToText(bytes);

    const parsed = tryParseJson(text);
    if (Array.isArray(parsed?.data?.[0]?.embedding)) {
      return parsed.data[0].embedding;
    }

    const extracted = extractEmbeddingArrayFromText(text);
    if (Array.isArray(extracted)) return extracted;
  }

  return null;
}

return $input.all().map((item, index) => {
  const original = originalItems[index]?.json || {};
  const embedding = extractEmbedding(item.json);

  if (!Array.isArray(embedding)) {
    throw new Error(
      `Missing query embedding for item ${index}. Top-level keys: ${Object.keys(item.json || {}).join(', ')}`
    );
  }

  return {
    json: {
      ...original,

      qdrant_search_body: JSON.stringify({
        vector: embedding,
        limit: 10,
        with_payload: true,
        with_vector: false,
        filter: {
          must: [
            {
              key: 'status',
              match: {
                value: 'active'
              }
            },
            {
              key: 'retrieval_eligible',
              match: {
                value: true
              }
            }
          ],
          must_not: [
            {
              key: 'source_type',
              match: {
                value: 'mini_wiki'
              }
            }
          ]
        }
      })
    }
  };
});

const searchItems = $input.all();
const originalItems = $('Build Qdrant search body').all();

function parseStreamBuffer(json) {
  const chunks = json?._readableState?.buffer;

  if (!Array.isArray(chunks)) {
    return null;
  }

  const bytes = [];

  for (const chunk of chunks) {
    const data = chunk?.data;

    if (Array.isArray(data)) {
      bytes.push(...data);
    }
  }

  if (bytes.length === 0) {
    return null;
  }

  const text = new TextDecoder().decode(Uint8Array.from(bytes));

  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error(`Cannot parse Qdrant stream buffer as JSON: ${error.message}`);
  }
}

function extractQdrantResponse(json) {
  // Нормальный JSON-ответ
  if (Array.isArray(json.result)) {
    return json;
  }

  // Если n8n завернул ответ в data/body/response
  if (Array.isArray(json.data?.result)) {
    return json.data;
  }

  if (Array.isArray(json.body?.result)) {
    return json.body;
  }

  if (Array.isArray(json.response?.result)) {
    return json.response;
  }

  // Текущий случай: n8n вернул stream/buffer
  const parsedFromStream = parseStreamBuffer(json);

  if (parsedFromStream && Array.isArray(parsedFromStream.result)) {
    return parsedFromStream;
  }

  return {
    result: [],
    status: json.status || '',
    time: json.time || ''
  };
}

return searchItems.map((item, index) => {
  const original = originalItems[index]?.json;

  if (!original) {
    throw new Error(`Original search body not found for item ${index}`);
  }

  const qdrantResponse = extractQdrantResponse(item.json);
  const result = qdrantResponse.result || [];

  const formattedResults = result.map((hit, hitIndex) => {
    const payload = hit.payload || {};

    return {
      rank: hitIndex + 1,
      score: hit.score,
      id: hit.id,
      doc_id: payload.doc_id || '',
      chunk_id: payload.chunk_id || '',
      title: payload.title || '',
      url: payload.url || '',
      topic: payload.topic || '',
      chunk_text: payload.chunk_text || ''
    };
  });

  return {
    json: {
      ...original,
      search_results: formattedResults,
      retrieved_doc_ids: [...new Set(formattedResults.map(r => r.doc_id).filter(Boolean))].join(','),
      top_score: formattedResults[0]?.score || '',
      qdrant_raw_status: qdrantResponse.status || '',
      qdrant_result_count: formattedResults.length
    }
  };
});

const items = $input.all();

return items.map(item => {
  const input = item.json;
  const { qdrant_search_body, search_results, ...cleanInput } = input;
  const results = Array.isArray(search_results) ? search_results : [];

  const base = results.filter(r => r.rank <= 5).slice(0, 5);
  const anchorDocIds = [...new Set(base.slice(0, 2).map(r => r.doc_id).filter(Boolean))];

  const expanded = results
    .filter(r => r.rank > 5 && r.rank <= 10 && anchorDocIds.includes(r.doc_id))
    .slice(0, 3);

  const seen = new Set();
  const selected = [...base, ...expanded]
    .filter(r => {
      const key = `${r.doc_id}::${r.chunk_id}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 8);

  if (selected.length === 0) {
    return { json: { ...cleanInput, has_context: false, retrieved_context: '', sources: [], context_base_count: 0, context_expanded_count: 0, context_total_count: 0, anchor_doc_ids: anchorDocIds } };
  }

  const context = selected.map((result, index) => [
    `SOURCE ${index + 1}`,
    `retrieval_rank: ${result.rank}`,
    `doc_id: ${result.doc_id}`,
    `chunk_id: ${result.chunk_id}`,
    `title: ${result.title}`,
    `url: ${result.url}`,
    `score: ${result.score}`,
    'text:',
    result.chunk_text
  ].join('\n')).join('\n\n---\n\n');

  const sources = selected.map((result, index) => ({
    rank: result.rank,
    context_rank: index + 1,
    score: result.score,
    doc_id: result.doc_id,
    chunk_id: result.chunk_id,
    title: result.title,
    url: result.url
  }));

  return {
    json: {
      ...cleanInput,
      has_context: true,
      retrieved_context: context,
      sources,
      context_base_count: base.length,
      context_expanded_count: expanded.length,
      context_total_count: selected.length,
      anchor_doc_ids: anchorDocIds
    }
  };
});

