const responseItems = $input.all();
const originalItems = $('Build retrieved context').all();
const FALLBACK = 'В базе знаний нет достаточной информации для ответа на этот вопрос';

function tryParseJson(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(text.trim()); } catch { return null; }
}

function extractOpenAIResponse(json) {
  if (json?.choices?.[0]?.message?.content) return json;
  if (json?.body?.choices?.[0]?.message?.content) return json.body;
  if (json?.data?.choices?.[0]?.message?.content) return json.data;
  if (json?.response?.choices?.[0]?.message?.content) return json.response;
  for (const key of ['body','data']) {
    if (typeof json?.[key] === 'string') {
      const parsed = tryParseJson(json[key]);
      if (parsed?.choices?.[0]?.message?.content) return parsed;
    }
  }
  return json || {};
}

function isFallbackText(text) {
  const s = String(text || '').trim().toLowerCase();
  return s.startsWith('в базе знаний нет достаточной информации') ||
    s.startsWith('в базе знаний недостаточно информации') ||
    s.startsWith('нет достаточной информации для ответа') ||
    s.startsWith('по базе знаний невозможно однозначно ответить');
}

function extractCitations(answer) {
  return [...String(answer || '').matchAll(/\[([a-zA-Z0-9_/-]+)\s*\/\s*([a-zA-Z0-9_/-]+)\]/g)]
    .map(m => ({ doc_id: m[1], chunk_id: m[2], full: m[0] }));
}

return responseItems.map((item, index) => {
  const response = extractOpenAIResponse(item.json);
  const original = originalItems[index]?.json;
  if (!original) throw new Error(`Original retrieved context not found for item ${index}`);

  const usage = response.usage || {};
  let answer = String(response.choices?.[0]?.message?.content || '').trim();
  answer = answer.replace(/\n*\s*Источники\s*:\s*(?:отсутствуют|нет|не указаны)[^\n]*$/i, '').trim();

  let isFallback = isFallbackText(answer);
  const allowedSources = Array.isArray(original.sources) ? original.sources : [];
  const citations = extractCitations(answer);
  const normalizedCitations = [];
  const invalidCitations = [];

  for (const citation of citations) {
    let chunkId = citation.chunk_id;
    if (/^chunk_\d+$/i.test(chunkId)) chunkId = `${citation.doc_id}_${chunkId}`;

    const allowed = allowedSources.some(s => s.doc_id === citation.doc_id && s.chunk_id === chunkId);
    const permittedDoc = citation.doc_id.startsWith('npd_') && !citation.doc_id.startsWith('wiki_');

    if (allowed && permittedDoc) {
      normalizedCitations.push({ doc_id: citation.doc_id, chunk_id: chunkId });
      const canonical = `[${citation.doc_id} / ${chunkId}]`;
      if (citation.full !== canonical) answer = answer.replace(citation.full, canonical);
    } else {
      invalidCitations.push({ doc_id: citation.doc_id, chunk_id: chunkId });
    }
  }

  const hasMissingCitations = !isFallback && normalizedCitations.length === 0;
  const hasInvalidCitations = invalidCitations.length > 0 || hasMissingCitations;

  if (isFallback || hasInvalidCitations) {
    answer = FALLBACK;
    isFallback = true;
  }

  const unique = [];
  const seen = new Set();
  for (const c of normalizedCitations) {
    const key = `${c.doc_id}::${c.chunk_id}`;
    if (!seen.has(key)) { seen.add(key); unique.push(c); }
  }

  return { json: {
    ...original,
    timestamp: new Date().toISOString(),
    answer,
    telegram_answer: answer,
    sources_in_answer: isFallback ? '' : unique.map(c => `${c.doc_id} / ${c.chunk_id}`).join(','),
    verified_sources: isFallback ? [] : unique,
    invalid_sources_detected: hasMissingCitations ? [{ reason: 'missing_valid_citation' }] : invalidCitations,
    source_verification_passed: !hasInvalidCitations,
    model: response.model || '',
    prompt_tokens: usage.prompt_tokens || 0,
    completion_tokens: usage.completion_tokens || 0,
    total_tokens: usage.total_tokens || 0,
    status: isFallback ? 'fallback' : 'answered',
    full_fallback_detected: isFallback
  }};
});

return $input.all().map(item => ({
  json: {
    ...item.json,
    timestamp: new Date().toISOString(),
    answer: item.json.answer,
    sources_in_answer: '',
    model: 'safety_guard',
    prompt_tokens: 0,
    completion_tokens: 0,
    total_tokens: 0,
    sources: [],
    retrieved_doc_ids: '',
    top_score: '',
    status: 'blocked'
  }
}));

const inputItems = $input.all();

const unsafePatterns = [
  /(?:^|[^а-яё])как\s+(?:скрыть|скрывать|спрятать|занизить)\s+(?:доход|выручк|налог)/i,
  /(?:^|[^а-яё])как\s+не\s+(?:платить|показывать|указывать|отражать)\s+(?:налог|доход|выручк)/i,
  /(?:^|[^а-яё])как\s+(?:обойти|уклониться\s+от)\s+(?:налог|запрет|ограничени|правил)/i,
  /(?:^|[^а-яё])(?:обойти|обход)\s+(?:запрет|ограничени|правил|двухлетн|2[- ]?летн)/i,
  /(?:фиктивн|поддельн|вымышленн)[а-яё]*\s+(?:чек|имя|договор|услуг|доход)/i,
  /(?:не\s+формировать|не\s+пробивать|сразу\s+аннулировать)[а-яё\s]*чек/i,
  /(?:скрыть|занизить|не\s+показывать|не\s+отражать)\s+(?:доход|выручк|налог)/i,
  /(?:уклониться\s+от|обойти)\s+(?:налог|запрет|ограничени|правил)/i,
  /(?:чуж(?:ую|ой)|дедушк|бабушк|родственник)[а-яё-]*\s+(?:карт|самозанят)/i,
  /(?:контрафакт|пален)[а-яё-]*\s+товар/i
];

return inputItems.map(item => {
  const input = item.json;
  const questionOriginal = String(input.user_question || input.question || '').trim();
  const question = questionOriginal.toLowerCase();

  const baseFields = {
    ...input,
    question_id: input.question_id || '',
    category: input.category || '',
    question: questionOriginal,
    user_question: questionOriginal,
    answer_question: input.answer_question || questionOriginal,
    search_query: input.search_query || questionOriginal,
    search_question: input.search_question || questionOriginal,
    expected_behavior: input.expected_behavior || '',
    expected_source_doc: input.expected_source_doc || '',
    notes: input.notes || ''
  };

  if (!questionOriginal) {
    return { json: { ...baseFields, route: 'blocked', answer: 'Вопрос пустой. Укажите вопрос по налогу на профессиональный доход.', sources: [], safety_reason: 'empty_question' } };
  }

  const isUnsafe = unsafePatterns.some(pattern => pattern.test(question));

  if (isUnsafe) {
    return { json: { ...baseFields, route: 'blocked', answer: 'Я не могу помогать со скрытием доходов, уклонением от налогов или нарушением правил НПД. Могу объяснить, как правильно отражать доходы, формировать чеки и платить налог на профессиональный доход.', sources: [], safety_reason: 'tax_evasion_request' } };
  }

  return { json: { ...baseFields, route: 'rag' } };
});

