const judgeItems = $input.all();
const answerItems = $('Prepare answer for judge').all();

function isByteLikeArray(value) {
  if (!Array.isArray(value)) return false;

  return value.length > 0 && value.every(x =>
    typeof x === 'number' &&
    Number.isInteger(x) &&
    x >= 0 &&
    x <= 255
  );
}

function isNumericObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;

  const keys = Object.keys(value);

  return keys.length > 0 && keys.every(key => /^\d+$/.test(key));
}

function numericObjectToArray(value) {
  return Object.keys(value)
    .sort((a, b) => Number(a) - Number(b))
    .map(key => value[key]);
}

function decodeBytes(value) {
  let arr = null;

  if (isByteLikeArray(value)) {
    arr = value;
  } else if (isNumericObject(value)) {
    const maybeArr = numericObjectToArray(value);
    if (isByteLikeArray(maybeArr)) {
      arr = maybeArr;
    }
  }

  if (!arr) return null;

  try {
    return new TextDecoder().decode(Uint8Array.from(arr));
  } catch (error) {
    return null;
  }
}

function tryParseJson(text) {
  if (typeof text !== 'string') return null;

  const trimmed = text.trim();
  if (!trimmed) return null;

  try {
    return JSON.parse(trimmed);
  } catch (error) {
    return null;
  }
}

function getOpenAIContent(obj) {
  if (obj?.choices?.[0]?.message?.content) {
    return obj.choices[0].message.content;
  }

  return null;
}

function extractFromStreamBuffer(obj) {
  const chunks = obj?._readableState?.buffer;
  if (!Array.isArray(chunks)) return null;

  const bytes = [];

  for (const chunk of chunks) {
    if (Array.isArray(chunk?.data)) {
      bytes.push(...chunk.data);
    }
  }

  if (!bytes.length) return null;

  const text = decodeBytes(bytes);
  if (!text) return null;

  return tryParseJson(text);
}

function recursiveFindContent(value, depth = 0) {
  if (depth > 6 || value == null) return null;

  // 1. Прямой OpenAI JSON
  const direct = getOpenAIContent(value);
  if (direct) return direct;

  // 2. Если value — строка JSON
  if (typeof value === 'string') {
    const parsed = tryParseJson(value);
    if (parsed) {
      return recursiveFindContent(parsed, depth + 1);
    }
    return null;
  }

  // 3. Если value — byte array или numeric object
  const decodedText = decodeBytes(value);
  if (decodedText) {
    const parsed = tryParseJson(decodedText);
    if (parsed) {
      return recursiveFindContent(parsed, depth + 1);
    }
  }

  // 4. Если value — stream/buffer
  const streamParsed = extractFromStreamBuffer(value);
  if (streamParsed) {
    return recursiveFindContent(streamParsed, depth + 1);
  }

  // 5. Если object/array — ищем внутри популярных и всех остальных полей
  if (typeof value === 'object') {
    const priorityKeys = [
      'json',
      'body',
      'data',
      'response',
      'result',
      'content',
      'message'
    ];

    for (const key of priorityKeys) {
      if (value[key] !== undefined) {
        const found = recursiveFindContent(value[key], depth + 1);
        if (found) return found;
      }
    }

    for (const key of Object.keys(value)) {
      if (priorityKeys.includes(key)) continue;

      const found = recursiveFindContent(value[key], depth + 1);
      if (found) return found;
    }
  }

  return null;
}

function parseJudgeJson(text) {
  const raw = String(text || '').trim();

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  if (!cleaned) {
    return {
      judge_score: 0,
      judge_result: 'judge_empty_response',
      source_correct: false,
      fallback_correct: false,
      safety_correct: false,
      reason: 'Judge returned empty response or response path was not found.'
    };
  }

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return {
      judge_score: 0,
      judge_result: 'judge_parse_error',
      source_correct: false,
      fallback_correct: false,
      safety_correct: false,
      reason: `Judge JSON parse error: ${error.message}. Raw: ${cleaned.slice(0, 500)}`
    };
  }
}

return judgeItems.map((item, index) => {
  const original = answerItems[index]?.json;

  if (!original) {
    throw new Error(`Original final answer not found for item ${index}`);
  }

  const judgeText = recursiveFindContent(item.json);
  const judge = parseJudgeJson(judgeText);

  return {
    json: {
      run_id: original.run_id || `eval_v0_2_${new Date().toISOString().slice(0, 10)}`,
      timestamp: original.timestamp || new Date().toISOString(),

      question_id: original.question_id,
      category: original.category,
      question: original.question,
      expected_behavior: original.expected_behavior,
      expected_source_doc: original.expected_source_doc,

      retrieved_doc_ids: original.retrieved_doc_ids,
      top_score: original.top_score,
      answer: original.answer,
      sources_in_answer: original.sources_in_answer,

      judge_score: judge.judge_score ?? 0,
      judge_result: judge.judge_result || 'unknown',
      judge_reason: judge.reason || '',

      prompt_tokens: original.prompt_tokens,
      completion_tokens: original.completion_tokens,
      total_tokens: original.total_tokens,
      model: original.model,
      status: original.status
    }
  };
});

const runId = `eval_v0_3_${new Date().toISOString().replace(/[:.]/g, '-')}`;

return $input.all()
  .filter(item => String(item.json.question || '').trim())
  .map(item => {
    const question = String(item.json.question || '').trim();

    return {
      json: {
        ...item.json,
        run_id: runId,
        user_question: question,
        answer_question: question,
        search_query: question,
        search_question: question
      }
    };
  });

function bytesToText(bytes) {
