function collectReadableStateBytes(value) {
  const buffers = value?._readableState?.buffer;

  if (!Array.isArray(buffers)) {
    return [];
  }

  const bytes = [];

  for (const item of buffers) {
    if (item?.type === 'Buffer' && Array.isArray(item.data)) {
      bytes.push(...item.data);
      continue;
    }

    if (Array.isArray(item?.data)) {
      bytes.push(...item.data);
      continue;
    }
  }

  return bytes;
}

function normalizeQdrantResponse(json) {
  // Нормальный JSON от Qdrant
  if (json?.result) {
    return json;
  }

  if (json?.body?.result) {
    return json.body;
  }

  if (json?.data?.result) {
    return json.data;
  }

  // Если body/data — строка JSON
  if (typeof json?.body === 'string') {
    const parsed = tryParseJson(json.body);
    if (parsed?.result) return parsed;
  }

  if (typeof json?.data === 'string') {
    const parsed = tryParseJson(json.data);
    if (parsed?.result) return parsed;
  }

  // Если пришёл stream/buffer от n8n
  const bytes = collectReadableStateBytes(json);

  if (bytes.length > 0) {
    const text = bytesToText(bytes);
    const parsed = tryParseJson(text);

    if (parsed?.result) {
      return parsed;
    }

    throw new Error(`Could not parse Qdrant buffer. Text preview: ${text.slice(0, 500)}`);
  }

  return json;
}

function extractPoints(qdrantResponse) {
  const result = qdrantResponse?.result;

  // /points/search обычно возвращает result как массив
  if (Array.isArray(result)) {
    return result;
  }

  // /points/scroll возвращает result.points
  if (Array.isArray(result?.points)) {
    return result.points;
  }

  return [];
}

return $input.all().map(item => {
  const input = item.json;
  const qdrantResponse = normalizeQdrantResponse(input);
  const points = extractPoints(qdrantResponse);

  const formatted = points.map((point, index) => {
    const p = point.payload || {};

    return {
      rank: index + 1,
      score: point.score ?? null,
      doc_id: p.doc_id || p.wiki_id || '',
      chunk_id: p.chunk_id || '',
      title: p.title || '',
      topic: p.topic || '',
      source_type: p.source_type || 'mini_wiki',
      can_be_cited: p.can_be_cited === true ? true : false,
      linked_raw_documents: p.linked_raw_documents || [],
      chunk_text: p.chunk_text || ''
    };
  });

  return {
    json: {
      ...input,
      mini_wiki_results: formatted,
      mini_wiki_doc_ids: [...new Set(formatted.map(x => x.doc_id).filter(Boolean))],
      mini_wiki_chunk_ids: formatted.map(x => x.chunk_id).filter(Boolean)
    }
  };
});

return $input.all().map(item => {
  const input = item.json;
  const results = input.mini_wiki_results || [];

  const blocks = results.map((r, index) => {
    return [
      `MINI-WIKI ${index + 1}`,
      `doc_id: ${r.doc_id}`,
      `chunk_id: ${r.chunk_id}`,
      `title: ${r.title}`,
      `topic: ${r.topic}`,
      `can_be_cited: false`,
      `linked_raw_documents: ${Array.isArray(r.linked_raw_documents) ? r.linked_raw_documents.join(', ') : ''}`,
      `text:`,
      r.chunk_text
    ].join('\n');
  });

  return {
    json: {
      ...input,
      mini_wiki_context: blocks.join('\n\n---\n\n'),
      mini_wiki_doc_ids: input.mini_wiki_doc_ids || [],
      mini_wiki_chunk_ids: input.mini_wiki_chunk_ids || []
    }
  };
});

